        if ample_supply and hp >= 7 and no_water == 0:
            bid = 8.0
        elif hp >= 6:
            bid = 15.0
        else:
            bid = 40.0
        return max(0.0, min(budget, bid))

    if soft_count > 0:
        target = max(45.0, lowest_prev + 2.0)
        if tight_supply:
            target += 8.0
        if hp <= 6:
            target += 10.0
        bid = target
    else:
        bid = 28.0
